import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapHikingPositionToFullFront,
  mapHikingVacancyResponseToFront,
  mapHikingVacancyToFront,
} from '../@mappers/hikingPositionsAndVacancies.mapper';
import {
  IHikingPositionDTO,
  IHikingVacancyAddDto,
  IHikingVacancyDTO,
  IHikingVacancyResponseDto,
  IHikingVacancyUpdateDto,
} from '../@types/DTO/hikingPositionsAndVacancies.dto.types';

export const getHikingVacancies = async (id_hiking: number) => {
  const res = await get('/ajax/hiking/vacancies/vacancies_list.php', { id_hiking }).then<
    IHikingVacancyDTO[]
  >(handleApiError);

  return res.map(mapHikingVacancyToFront);
};

export const getAllPositions = async () => {
  const res = await get('/ajax/hiking/positions_list.php').then<IHikingPositionDTO[]>(
    handleApiError,
  );

  return res.map(mapHikingPositionToFullFront);
};

export const getOnePosition = async (id_position: number) => {
  const res = await get('/ajax/hiking/position_info.php', {
    id: id_position,
  }).then<IHikingPositionDTO>(handleApiError);

  return mapHikingPositionToFullFront(res);
};

export const addVacancy = async (data: IHikingVacancyAddDto) => {
  const res = await post<{ id: string }, IHikingVacancyAddDto>(
    '/ajax/hiking/vacancies/vacancy_add.php',
    data,
  ).then<{ id: string }>(handleApiError);
  return +res.id;
};

export const deleteVacancy = async (id_hiking: number, id: number) => {
  const res = await post('/ajax/hiking/vacancies/vacancy_del.php', { id_hiking, id }).then<{
    success: boolean;
  }>(handleApiError);
  return res.success;
};

export const editVacancy = async (data: IHikingVacancyUpdateDto) => {
  const res = await post('/ajax/hiking/vacancies/vacancy_edit.php', data).then<{
    success: boolean;
  }>(handleApiError);
  return res.success;
};

export const getHikingVacancyResponses = async (id_vacancy: number, id_hiking: number) => {
  const res = await get('/ajax/hiking/vacancies/get_responses_for_vacancy.php', {
    id_vacancy,
    id_hiking,
  }).then<IHikingVacancyResponseDto[]>(handleApiError);

  return res.map(mapHikingVacancyResponseToFront);
};
export const approveVacancy = async (id_hiking: number, id_hiking_vacancy_response: number) => {
  const res = await post('/ajax/hiking/vacancies/vacancy_approve.php', {
    id_hiking,
    id_hiking_vacancy_response,
  }).then<{ success: boolean }>(handleApiError);

  return !!res.success;
};

export const hikingVacancyAddResponse = async (data: { id_hiking: number; id_vacancy: number }) => {
  return post('/ajax/hiking/vacancies/vacancy_add_response.php', data).then<{
    success: boolean;
    id: number;
  }>(handleApiError);
};
